SELECT * FROM stock_watch_technical_analysis
WHERE symbol = #{symbol}
  AND market = #{market}
  AND analysis_date = #{analysisDate}
  AND run_slot = #{runSlot}
  AND COALESCE(period_type, 'DAY') = #{periodType}
  AND (period_key = #{periodKey} OR (period_key IS NULL AND #{periodType} = 'DAY'))
ORDER BY id DESC
LIMIT 1

SELECT * FROM stock_watch_technical_analysis
WHERE symbol = #{symbol}
  AND market = #{market}
  AND analysis_date >= #{startDate}
  AND analysis_date <= #{endDate}
  AND COALESCE(period_type, 'DAY') = #{periodType}
ORDER BY analysis_date DESC, gmt_create DESC, id DESC

SELECT * FROM stock_watch_technical_analysis
WHERE symbol = #{symbol}
  AND market = #{market}
  AND COALESCE(period_type, 'DAY') = #{periodType}


          AND period_key IN

              #{key}



          AND 1 = 0


ORDER BY analysis_date DESC, gmt_create DESC, id DESC

SELECT * FROM stock_watch_technical_analysis
WHERE symbol = #{symbol}
  AND market = #{market}
  AND COALESCE(period_type, 'DAY') = #{periodType}
ORDER BY gmt_create DESC, id DESC
LIMIT #{limit}

SELECT * FROM stock_watch_technical_analysis
WHERE symbol = #{symbol}
  AND market = #{market}
  AND status = 'SUCCESS'
  AND analysis_date >= #{startDate}
  AND analysis_date <= #{endDate}
  AND COALESCE(period_type, 'DAY') = #{periodType}
ORDER BY analysis_date ASC, gmt_create ASC, id ASC
LIMIT #{limit}

SELECT * FROM stock_watch_technical_analysis
WHERE symbol = #{symbol}
  AND market = #{market}
  AND status = 'SUCCESS'
  AND gmt_create >= #{activeFrom}
ORDER BY gmt_create ASC, id ASC
LIMIT #{limit}
